from pathlib import Path
import re,json,pandas as pd
P=Path(__file__).resolve().parent;R=P.parent;D=R/'manuscript/sections';O=P/'results'
parts={p.stem:p.read_text() for p in D.glob('*.md')};changes=[]
def para(sec,prefix,new):
 m=re.search(r'(?m)^'+re.escape(prefix)+r'[^\n]*',parts[sec]);assert m,(sec,prefix);changes.append(dict(section=sec,kind='replace',old=m[0],new=new));parts[sec]=parts[sec][:m.start()]+new+parts[sec][m.end():]
def before(sec,needle,new):
 assert parts[sec].count(needle)==1,(sec,needle);parts[sec]=parts[sec].replace(needle,new.strip()+'\n\n'+needle);changes.append(dict(section=sec,kind='insert',anchor=needle,new=new))
def fig(n,name,title,note):return f'Рисунок 2.{n}. {title}\n\n![{title}](../revision30/figures/{name}.png)\n\nИсточник: расчёты автора. {note}\n'
def fmt(x,n=4):return f'{x:.{n}f}'.replace('.',',')
S=pd.read_csv(O/'equity_scores.csv')
def val(h,m,guard='raw',sample='all'):return S[(S.h==h)&(S.model==m)&(S.guard==guard)&(S['sample']==sample)].iloc[0]
models=['HIST','AR','AR_ESI','AR_ESI_NFCI','AR_ESI_ANFCI','AR_ESI_EQ','AR_ESI_EQ_NFCI','AR_ESI_EQ_ANFCI'];labels={m:m.replace('_',' + ') for m in models}
